import { filingTitle, normaliseText } from '../helpers/text.js';

/**
 * Returns the items whose title or author holds every word of the query, sorted by title
 * the way librarians file them: a leading "The", "A" or "An" is ignored.
 */
export function searchCatalog(items, query) {
  const words = normaliseText(query).split(' ').filter(Boolean);
  if (words.length === 0) return [];
  return items
    .filter((item) => {
      const searchable = normaliseText(`${item.title} ${item.author}`);
      return words.every((word) => searchable.includes(word));
    })
    .sort((first, second) => filingTitle(first.title).localeCompare(filingTitle(second.title)));
}
/** Lower-cases text and turns every run of punctuation and spaces into one space, for matching. */
export function normaliseText(text) {
  return text
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();
}

/** Returns a title as librarians file it: without a leading "The", "A" or "An". */
export function filingTitle(title) {
  return title.trim().replace(/^(?:the|an?)\s+(?=\S)/i, '');
}

/** Replaces each {name} in a template by the value of that name; unknown names stay as they are. */
export function fillTemplate(template, values) {
  return template.replace(/\{(\w+)\}/g, (placeholder, name) =>
    name in values ? String(values[name]) : placeholder,
  );
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { isValidBarcode, normaliseBarcode } from '../lib/catalog/barcodes.js';
import { searchCatalog } from '../lib/catalog/search.js';
import { BOOK, DVD, LAPTOP, MAGAZINE } from './sample-library.js';

const items = [BOOK, DVD, LAPTOP, MAGAZINE];

test('finds the items whose title or author holds every word of the query', () => {
  assert.deepEqual(
    searchCatalog(items, 'le guin darkness').map((item) => item.id),
    [BOOK.id],
  );
  assert.deepEqual(
    searchCatalog(items, 'MIYAZAKI').map((item) => item.id),
    [DVD.id],
  );
});

test('sorts the results by title, ignoring a leading The, A or An', () => {
  assert.deepEqual(
    searchCatalog(items, 'a').map((item) => item.title),
    ['Chromebook 14', 'The Left Hand of Darkness', 'National Geographic, November 2026', 'Spirited Away'],
  );
});

test('finds nothing for an empty query', () => {
  assert.deepEqual(searchCatalog(items, '  '), []);
});

test('accepts a barcode with the right check digit only', () => {
  assert.equal(isValidBarcode('31234000000016'), true);
  assert.equal(isValidBarcode('31234000000017'), false);
  assert.equal(isValidBarcode('3123400000001'), false);
});

test('removes spaces and dashes from a scanned barcode', () => {
  assert.equal(normaliseBarcode('3123-4000 0000 16'), '31234000000016');
});
